contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function must take at least one parameter
    function run(uint amt) public payable {
        // This contract is the owner of c (deployed by the harness). No precondition on amt.

        // record before values (only public getters/observables)
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        // perform the owner-only withdraw call and capture whether it reverted
        bool reverted;
        c.withdraw(amt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        // General invariant: withdraw either reverts and leaves state unchanged,
        // or succeeds and does not increase depositsCount nor increase contract balance.
        assert(
            (reverted && afterCount == beforeCount && afterBal == beforeBal)
            || (!reverted && afterCount <= beforeCount && afterBal <= beforeBal)
        );
    }

    // accept Ether in case withdraw triggers sending back to this contract
    receive() external payable {}
}

