// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amt) internal {
        uint256 beforeCount;
        try c.depositsCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        uint beforeBal = address(c).balance;
        bool reverted;
        try c.withdraw(amt) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterCount;
        try c.depositsCount() returns (uint256 __r) { afterCount = __r; } catch { return; }
        uint afterBal = address(c).balance;
        assertTrue((reverted && afterCount == beforeCount && afterBal == beforeBal)
            || (!reverted && afterCount <= beforeCount && afterBal <= beforeBal));
    }

    function testFuzz_run(uint256 amt) public {
        _run(amt);
    }

    receive() external payable {}
}
